css:
.dark svg.lucide {
  stroke-width: 1.75;
  stroke-linecap: square;
  stroke-linejoin: miter;
}
.dark [data-chat-header] {
  background-image: linear-gradient(90deg, #74B8E8, #F06E2B);
  background-size: 100% 2px;
  background-position: 0 100%;
  background-repeat: no-repeat;
}
.dark [data-slot='composer-host']:focus-within {
  border-color: #74B8E8;
  box-shadow: 0 0 0 1px #74B8E8;
}
.dark [data-slot='scroll-area-thumb'] {
  background-color: #63728466;
  border-radius: 2px;
}
.dark [data-slot='scroll-area-thumb']:hover {
  background-color: #637284AA;
}
.dark ::selection {
  background-color: #1D3B57;
  color: #F4F5F8;
}
.dark input,
.dark textarea,
.dark .composer-tiptap {
  caret-color: #74B8E8;
}
.dark [data-thread-item][data-active='true'],
.dark [data-thread-item][aria-current='page'] {
  box-shadow: inset 2px 0 0 0 #74B8E8;
}
